mapper.select:
select a.id as asset_id, a.asset_code as asset_code, a.name as asset_name, c.name as category_name, a.department_name department_name, u.real_name as user_name, a.status as status, l.original_value as purchase_price, l.net_value as net_amount from asset a left join asset_category c on a.category_id = c.id left join asset_ledger l on a.id = l.asset_id left join user u on a.current_user_id = u.id
and a.category_id = #{categoryId}
and a.department_id = #{departmentId}
and a.status = #{status}

select ls.id as id, ls.snapshot_month as snapshot_month, ls.asset_code as asset_code, ls.asset_name as asset_name, ls.original_value as original_amount, ls.monthly_depreciation as monthly_depreciation, ls.accumulated_depreciation as accumulated_depreciation, ls.net_value as net_Amount from asset_ledger_snapshot ls left join asset a on a.id = ls.asset_id left join asset_category c on ls.category_name = c.name left join department d on ls.department_name = d.name
and ls.snapshot_month = #{snapshotMonth}
and ls.category_id = #{categoryId}
and ls.department_id = #{departmentId}
